// NB-01 · spec: .qa/e2e/specs/nearby.md 1.1 · только чтение (состояние согласия не меняется).
import { test, expect } from '../../fixtures';
import { openRole, saveSession, consentTitle, listTitle, emptyTitle, userIdOf } from './nearby-helpers';

test.use({ browserName: 'webkit' });

test.describe('היו כאן — משתמשים שהיו בקרבת מקום', () => {
  test('старый /nearby открывает сегмент «היו כאן» на экране «מיקום» @iphone (#67c751 #ab0123)', async ({ browser }) => {
    const reg1 = await openRole(browser, 'reg1');
    try {
      const p = reg1.page;
      await p.goto('/nearby');
      await p.waitForURL(/\/map\?tab=were-here/);
      await expect(p.getByRole('tab', { name: 'עכשיו' })).toBeVisible();
      await expect(p.getByRole('tab', { name: 'היו כאן' })).toBeVisible();
      await expect(p.getByText('MAGNET', { exact: true })).toBeVisible();
      await expect(p.getByRole('tab', { name: /מיקום/ })).toBeVisible();
      await expect(consentTitle(p).or(listTitle(p)).or(emptyTitle(p)).first()).toBeVisible();
      expect(userIdOf('reg1')).toBeTruthy();
    } finally {
      await saveSession(reg1);
      await reg1.ctx.close();
    }
  });
});
